begin;
create table public.hub_profiles(id uuid primary key references auth.users on delete cascade,display_name text not null check(char_length(display_name) between 1 and 40),department text not null default '기타',created_at timestamptz not null default now());
create table public.hub_posts(id uuid primary key default gen_random_uuid(),title text not null check(char_length(title) between 1 and 150),body text not null check(char_length(body) between 1 and 12000),category text not null check(category in ('공지사항','업무공유','안전·품질','질문과 답변','자유게시판')),department text not null default '전사',author_id uuid references auth.users on delete cascade,author_name text not null default '교육운영팀',is_sample boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.hub_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.hub_posts on delete cascade,body text not null check(char_length(body) between 1 and 2000),author_id uuid references auth.users on delete cascade,author_name text not null default '교육운영팀',is_sample boolean not null default false,created_at timestamptz not null default now());
create table public.hub_metrics(id bigint generated always as identity primary key,metric_date date not null,site text not null,production integer not null,target integer not null,quality_rate numeric not null,safety_checks integer not null,safety_target integer not null,unique(metric_date,site));
alter table public.hub_profiles enable row level security;alter table public.hub_posts enable row level security;alter table public.hub_comments enable row level security;alter table public.hub_metrics enable row level security;
create policy hub_profile_read on public.hub_profiles for select to authenticated using(id=auth.uid());
create policy hub_profile_insert on public.hub_profiles for insert to authenticated with check(id=auth.uid());
create policy hub_profile_update on public.hub_profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy hub_post_read on public.hub_posts for select to anon,authenticated using(is_sample or auth.uid() is not null);
create policy hub_post_insert on public.hub_posts for insert to authenticated with check(author_id=auth.uid() and not is_sample);
create policy hub_post_update on public.hub_posts for update to authenticated using(author_id=auth.uid() and not is_sample) with check(author_id=auth.uid() and not is_sample);
create policy hub_post_delete on public.hub_posts for delete to authenticated using(author_id=auth.uid() and not is_sample);
create policy hub_comment_read on public.hub_comments for select to anon,authenticated using(exists(select 1 from public.hub_posts p where p.id=post_id));
create policy hub_comment_insert on public.hub_comments for insert to authenticated with check(author_id=auth.uid() and not is_sample and exists(select 1 from public.hub_posts p where p.id=post_id));
create policy hub_comment_delete on public.hub_comments for delete to authenticated using(author_id=auth.uid() and not is_sample);
create policy hub_metrics_read on public.hub_metrics for select to anon,authenticated using(true);
revoke all on public.hub_profiles,public.hub_posts,public.hub_comments,public.hub_metrics from anon,authenticated;
grant select,insert,update on public.hub_profiles to authenticated;grant select on public.hub_posts,public.hub_comments,public.hub_metrics to anon,authenticated;grant insert,update,delete on public.hub_posts to authenticated;grant insert,delete on public.hub_comments to authenticated;
create function public.hub_stamp_author() returns trigger language plpgsql security definer set search_path=public as $$ begin if auth.uid() is not null then new.author_id=auth.uid();select display_name into new.author_name from public.hub_profiles where id=auth.uid();if new.author_name is null then new.author_name='새 멤버';end if;new.is_sample=false;end if;return new;end $$;
create trigger hub_posts_author before insert on public.hub_posts for each row execute function public.hub_stamp_author();create trigger hub_comments_author before insert on public.hub_comments for each row execute function public.hub_stamp_author();
create function public.hub_stamp_update() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end $$;create trigger hub_posts_updated before update on public.hub_posts for each row execute function public.hub_stamp_update();
insert into public.hub_posts(title,body,category,department,author_name,is_sample,created_at) values ('함께 만드는 스마트 워크, 워크허브에 오신 것을 환영합니다','이 공간은 직원 간 협업을 경험하기 위한 교육용 게시판입니다.

생산·품질·안전 수치와 게시글은 모두 가상 샘플입니다. 실제 회사 실적과 관계가 없습니다. 회원가입 후 글과 댓글을 작성해 보세요.','공지사항','전사','교육운영팀',true,now()-interval '1 hours'),('10월 현장 안전 점검 체크리스트 공유','작업 전 보호구 착용, 통로 확보, 장비 이상 유무를 확인해 주세요. 반복 점검 업무 중 자동화하고 싶은 항목을 댓글로 남겨 주세요.','안전·품질','창원','안전환경팀',true,now()-interval '8 hours'),('생산 실적 집계 시간을 줄이는 CSV 활용 팁','날짜·사업장·품목·계획수량·실적수량을 표준 항목으로 맞춰 보세요. 중복 행과 누락 데이터는 분석 전에 먼저 확인합니다.','업무공유','인천','생산기획팀',true,now()-interval '15 hours'),('S650 로더 3D 시뮬레이션 체험 안내','자동 운반 시연과 키보드 조작을 체험해 보세요.
https://gabkeunc-sys.github.io/bobcat-loader-lab/','업무공유','전사','DX교육팀',true,now()-interval '22 hours'),('불량 유형을 어떤 기준으로 나누면 좋을까요?','외관·치수·조립·작동 유형으로 나눌 때 중복 분류를 줄이는 방법을 함께 고민해 봅시다.','질문과 답변','창원','품질개선팀',true,now()-interval '29 hours'),('부서별 AI 활용 아이디어를 모집합니다','업무명·현재 소요시간·원하는 결과물 세 가지로 정리해 주세요. 작은 반복 업무부터 자동화해 봅시다.','공지사항','분당','교육운영팀',true,now()-interval '36 hours'),('자재 발주 검토에 납기 데이터를 함께 봅시다','재고와 평균 사용량, 납기를 함께 확인해 재고 소진 예상일과 입고 예정일을 비교합니다.','업무공유','인천','자재관리팀',true,now()-interval '43 hours'),('오늘 배운 자동화, 우리 업무에는 어떻게 적용할까요?','가장 먼저 적용해 보고 싶은 업무를 한 가지씩 남겨 주세요. 입력 자료와 판단 기준을 정리해 봅시다.','자유게시판','전사','DX교육팀',true,now()-interval '50 hours'),('설비 센서 데이터의 결측치는 어떻게 처리하나요?','보간 전에 설비 정지 구간인지 센서 통신 오류인지 구분해 보는 것이 좋을까요?','질문과 답변','창원','설비기술팀',true,now()-interval '57 hours'),('주간 협업 회의 자료는 한 페이지로 정리해 주세요','진행 현황 / 주요 이슈 / 필요한 결정 / 다음 주 계획. 수치에는 기준 기간과 단위를 함께 표기해 주세요.','공지사항','전사','경영지원팀',true,now()-interval '64 hours');
insert into public.hub_comments(post_id,body,author_name,is_sample) select id,'점검 결과를 표준 양식으로 모으면 다음 주에도 비교하기 좋겠습니다.','생산지원팀',true from public.hub_posts where category='안전·품질';
insert into public.hub_comments(post_id,body,author_name,is_sample) select id,'설비 정지와 통신 오류를 먼저 구분한 뒤 처리 방법을 정해 봅시다.','데이터분석팀',true from public.hub_posts where title='설비 센서 데이터의 결측치는 어떻게 처리하나요?';
insert into public.hub_metrics(metric_date,site,production,target,quality_rate,safety_checks,safety_target) select current_date-i,site,case site when '인천' then 98 else 81 end+((i*7+length(site))%19),case site when '인천' then 115 else 100 end,97.2+((i*3)%23)/10.0,8+((i+length(site))%3),10 from generate_series(0,13) i cross join (values('인천'),('창원')) s(site);
commit;select 'setup_complete' as result,(select count(*) from public.hub_posts) as posts,(select count(*) from public.hub_metrics) as metrics;